steps = [
    step("夹具里用“现在”:把同一个测试放到 2024-01-01 到 2025-12-31 共 731 天的每一天各跑一次(用注入的“今天”)。夹具 now().minusDays(30)、断言“相差不到 1 个月”:300 天失败,全部集中在 3、5、7、10、12 月(每个月份 2 年合计 60 天,即每年 30 天),例如 2024-03-01、03-02、03-03。夹具 now().minusDays(1)、断言“相差 1 个工作日”:208 天失败——周六 104 天、周日 104 天。把两个测试改成固定日期 2025-04-16(星期三):0 + 0 天失败。", t=tl(S(1)), done=lidx(S(1), '共 731 天', 'now().minusDays(30)'), mark=lidx(S(1), 'now().minusDays(1)', '2025-04-16'), b=bars([['minusDays(30):失败天数', 300, '300'], ['minusDays(1):失败天数', 208, '208'], ['固定日期:失败天数', 0, '0']], 300, done=[0, 1, 2]), kv=KV([['now() 夹具', '731 天里 300 天 / 208 天失败'], ['固定日期', '0 天失败']], ['now() 夹具'])),
    step("夹具里用随机数(数量 1..100,代码只在数量 ≥ 97 时有 bug):种子 1..1000 各跑一次,失败 41 次(4.1%),前 5 个失败种子 53、57、68、72、140。记下失败种子 53 后重放 10 次:失败 10 次,每次数量都是 97。每个测试用全新随机种子时,连续跑 1 / 3 / 10 / 50 / 100 次发现 bug 的概率是 3.8% / 10.8% / 34.2% / 87.8% / 98.1%。随机夹具不是“覆盖更多情况”,而是一个时灵时不灵的探测器;不记录种子就无法重放。", t=tl(S(2)), done=lidx(S(2), '种子 1..1000 各跑一次', '记录下失败种子 53'), mark=lidx(S(2), '连续跑 1 次发现 bug 的概率'), b=bars([['跑 1 次', 3.8, '3.8%'], ['跑 3 次', 10.8, '10.8%'], ['跑 10 次', 34.2, '34.2%'], ['跑 50 次', 87.8, '87.8%'], ['跑 100 次', 98.1, '98.1%']], 100, done=[0, 1, 2, 3, 4]), kv=KV([['种子 1..1000', '41 次失败(4.1%)'], ['重放失败种子 53', '10/10 失败,数量都是 97'], ['随机且不记种子', '连续 10 次只有 34.2% 发现']], ['重放失败种子 53'])),
    step("“默认夹具”的值被烤进期望值:6 个订单测试,设计 A 每个都断言总价的绝对值(如默认订单 110.00),设计 B 只断言各自要验证的那一项(折扣、运费或礼品包装)。基线两种设计都是 0 失败。改一个默认值或配置:国内运费 1000 → 1200:A 坏 4 个(A1、A2、A3、A6),B 坏 0 个;默认国家 CN → DE:A 坏 4 个,B 0 个;默认商品额 10000 → 12000:A 坏 5 个,B 0 个;默认等级 STANDARD → SILVER:A 坏 5 个,B 也坏 1 个(B3,优惠券折扣被等级折扣影响)。B 也不是完全隔离的。", t=tl(S(3)), done=lidx(S(3), '基线:A 失败', '国内运费 1000 → 1200', '默认国家 CN → DE'), mark=lidx(S(3), '默认商品额 10000 → 12000', '默认等级 STANDARD → SILVER'), b=bars([['运费 1000→1200:A', 4, '4'], ['默认国家→DE:A', 4, '4'], ['商品额→12000:A', 5, '5'], ['等级→SILVER:A', 5, '5'], ['等级→SILVER:B', 1, '1']], 6, done=[0, 1, 2, 3, 4]), kv=KV([['设计 A(断言总价)', '改一个默认值,坏 4–5 个测试'], ['设计 B(只断言要验证的项)', '坏 0–1 个测试']], ['设计 A(断言总价)'])),
    step("夹具的构造成本:每个测试的 @BeforeEach 构造一个“什么都有”的订单(500 行商品 + 100 项元数据)与一个只有一行的订单。5000 次构造(7 轮取中位数):重夹具每次 8.9 微秒(共 44 ms),轻夹具每次 0.01 微秒;按 2 万个测试估算,重夹具总共约 178 ms。这只是对象构造,不含数据库或文件:重夹具的代价主要不在时间,而在读测试的人要从一屏数据里找出哪个字段与断言有关。", t=tl(S(4)), done=lidx(S(4), '5000 个测试各构造一次'), mark=lidx(S(4), '按 2 万个测试估算'), b=bars([['重夹具(每次,微秒)', 8.9, '8.9 µs'], ['轻夹具(每次,微秒)', 0.01, '0.01 µs']], 9, done=[0, 1]), kv=KV([['重夹具 × 2 万个测试', '约 178 ms'], ['结论', '对象构造本身便宜,成本在可读性']], ['结论'])),
]
